      n => { const entries = [[0.2, 0.8, 0.16], [0.3, 1, 0.30], [0.4, 0.5, 0.20], [0.6, 0.5, 0.30], [0.25, 0.4, 0.10]]; const [x, p0, p] = entries[n]; return { topic: "Solutions", q: `A component has mole fraction ${x} in a solution. If its pure vapour pressure is ${p0} atm, its partial vapour pressure is:`, correct: `${p} atm`, wrong: [`${p0 / x} atm`, `${p0 - p} atm`, `${p * 2} atm`], explain: `Raoult's law gives p = x p° = ${x} × ${p0} = ${p} atm.` }; },
      n => { const entries = [[0.1, 0.082, 300, 2.46], [0.2, 0.082, 300, 4.92], [0.05, 0.082, 300, 1.23], [0.15, 0.082, 300, 3.69], [0.25, 0.082, 300, 6.15]]; const [c, r, t, pi] = entries[n]; return { topic: "Solutions", q: `An ideal solution has concentration ${c} mol L⁻¹ at ${t} K. Using R=0.082 L atm mol⁻¹ K⁻¹, its osmotic pressure is:`, correct: `${pi} atm`, wrong: [`${(c * r).toFixed(3)} atm`, `${(pi / 2).toFixed(2)} atm`, `${(pi * 2).toFixed(2)} atm`], explain: `Π=CRT=${c} × ${r} × ${t}=${pi} atm.` }; }
